(function () {
  'use strict';
  var d = document, root = d.documentElement;
  var $ = function (s, c) { return (c || d).querySelector(s); };
  var $$ = function (s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); };
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var hasIO = 'IntersectionObserver' in window;
  var canHover = window.matchMedia && window.matchMedia('(hover: hover)').matches;

  function ready(fn) { if (d.readyState !== 'loading') { fn(); } else { d.addEventListener('DOMContentLoaded', fn); } }

  ready(function () {
    if (reduce || !hasIO) { root.classList.add('no-reveal'); }

    /* ---- 1. Wrap trailing arrows so they can slide on hover ---- */
    $$('.btn, .read-more, .post-nav a').forEach(function (el) {
      if (el.querySelector('.arr')) { return; }
      var walker = d.createTreeWalker(el, NodeFilter.SHOW_TEXT, null), n, nodes = [];
      while ((n = walker.nextNode())) { nodes.push(n); }
      nodes.forEach(function (t) {
        var m = t.nodeValue.match(/^([\s\S]*?)([→←])(\s*)$/) || t.nodeValue.match(/^()([→←])(\s[\s\S]*)$/);
        if (!m) { return; }
        var sp = d.createElement('span'); sp.className = 'arr'; sp.textContent = m[2]; sp.setAttribute('aria-hidden', 'true');
        var parent = t.parentNode;
        if (t.nodeValue.charAt(0) === m[2]) { parent.insertBefore(sp, t); t.nodeValue = m[3]; }
        else { t.nodeValue = m[1]; parent.insertBefore(sp, t.nextSibling); }
      });
    });

    /* ---- 2. Click ripple on buttons ---- */
    if (!reduce) {
      d.addEventListener('pointerdown', function (e) {
        var b = e.target.closest ? e.target.closest('.btn, .icon-btn, .share-btn, .to-top') : null;
        if (!b) { return; }
        var r = b.getBoundingClientRect(), s = Math.max(r.width, r.height) * 2;
        var dot = d.createElement('span'); dot.className = 'ripple-dot';
        dot.style.width = dot.style.height = s + 'px';
        dot.style.left = (e.clientX - r.left - s / 2) + 'px';
        dot.style.top = (e.clientY - r.top - s / 2) + 'px';
        b.appendChild(dot);
        setTimeout(function () { if (dot.parentNode) { dot.parentNode.removeChild(dot); } }, 700);
      }, { passive: true });
    }

    /* ---- 3. Magnetic hero / CTA buttons ---- */
    if (!reduce && canHover) {
      $$('.hero-cta .btn, .cta-buttons .btn, .nav-cta').forEach(function (b) {
        b.classList.add('magnetic');
        b.addEventListener('mousemove', function (e) {
          var r = b.getBoundingClientRect(), x = e.clientX - r.left - r.width / 2, y = e.clientY - r.top - r.height / 2;
          b.style.transform = 'translate(' + (x * 0.18) + 'px,' + (y * 0.25 - 3) + 'px)';
        });
        b.addEventListener('mouseleave', function () { b.style.transform = ''; });
      });
    }

    /* ---- 4. Post card pointer glow ---- */
    if (canHover) {
      d.addEventListener('mousemove', function (e) {
        var c = e.target.closest ? e.target.closest('.post-card') : null;
        if (!c) { return; }
        var r = c.getBoundingClientRect();
        c.style.setProperty('--gx', (e.clientX - r.left) + 'px');
        c.style.setProperty('--gy', (e.clientY - r.top) + 'px');
      }, { passive: true });
    }

    /* ---- 5. Single post: slide each content block in ---- */
    var body = $('.post-detail .post-body');
    if (body && hasIO && !reduce) {
      var blocks = Array.prototype.slice.call(body.children).filter(function (el) { return !el.classList.contains('toc'); });
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); io.unobserve(en.target); } });
      }, { rootMargin: '0px 0px -6% 0px', threshold: 0.06 });
      blocks.forEach(function (el, i) {
        el.classList.add('mo');
        if (/^H[23]$/.test(el.tagName)) { el.classList.add('mo-l'); }
        else if (el.tagName === 'BLOCKQUOTE') { el.classList.add('mo-r'); }
        else if (el.querySelector && el.querySelector('img') && !el.textContent.trim()) { el.classList.add(i % 2 ? 'mo-r' : 'mo-l'); }
        el.style.setProperty('--d', '0s');
        io.observe(el);
      });
      var toc = $('.toc', body); if (toc) { toc.classList.add('mo'); io.observe(toc); }
      $$('.share-bar, .author-box, .post-nav .prev, .post-nav .next, .related, .comments').forEach(function (el) {
        el.classList.add('mo');
        if (el.classList.contains('prev')) { el.classList.add('mo-l'); }
        if (el.classList.contains('next')) { el.classList.add('mo-r'); }
        io.observe(el);
      });
      $$('.share-bar .share-btn').forEach(function (b, i) { b.style.animation = 'moPop .5s var(--ease-spring) ' + (0.1 * i + 0.1) + 's both'; });
    }

    /* ---- 6. Stagger cards that sit in the same row ---- */
    $$('.posts-wrapper').forEach(function (w) {
      Array.prototype.forEach.call(w.querySelectorAll('.post-card'), function (c, i) {
        c.style.setProperty('--d', ((i % 3) * 0.1) + 's');
      });
    });

    /* ---- 7. Smooth anchor offset + section underline fallback ---- */
    $$('.section-header').forEach(function (h) { if (!hasIO || reduce) { h.classList.add('in'); } });
  });
})();
