(function () {
  'use strict';
  var d = document, root = d.documentElement;
  var $ = function (s, c) { return (c || d).querySelector(s); };
  var $$ = function (s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); };
  var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var hasIO = 'IntersectionObserver' in window;
  function ready(fn) { if (d.readyState !== 'loading') { fn(); } else { d.addEventListener('DOMContentLoaded', fn); } }

  ready(function () {
    var body = $('.post-detail .post-body');
    var postTitle = $('.post-detail .post-title');

    /* ---- 1. Motion-graphic titles: split into words, rise out of a mask ---- */
    function splitTitle(el, highlight) {
      if (!el || el.getAttribute('data-kt') || el.children.length) { return false; }
      var txt = (el.textContent || '').replace(/\s+/g, ' ').trim();
      if (!txt) { return false; }
      var words = txt.split(' ');
      el.setAttribute('data-kt', '1');
      el.setAttribute('aria-label', txt);
      el.textContent = '';
      words.forEach(function (w, i) {
        var o = d.createElement('span'), n = d.createElement('span');
        o.className = 'kw' + (highlight && words.length > 1 && i === words.length - 1 ? ' kw-hl' : '');
        o.setAttribute('aria-hidden', 'true');
        n.className = 'kw-i'; n.style.setProperty('--i', i); n.textContent = w;
        o.appendChild(n); el.appendChild(o);
        if (i < words.length - 1) { el.appendChild(d.createTextNode(' ')); }
      });
      el.classList.add('kt');
      return true;
    }
    if (!reduce) {
      if (splitTitle(postTitle, true)) {
        window.requestAnimationFrame(function () { window.requestAnimationFrame(function () { postTitle.classList.add('kt-play'); }); });
      }
      var titles = $$('.section-title').filter(function (el) { return splitTitle(el, true); });
      if (titles.length) {
        if (hasIO) {
          var tio = new IntersectionObserver(function (entries) {
            entries.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('kt-play'); tio.unobserve(en.target); } });
          }, { threshold: 0.5 });
          titles.forEach(function (el) { tio.observe(el); });
        } else { titles.forEach(function (el) { el.classList.add('kt-play'); }); }
      }
    }

    /* ---- 2. Single post: SEO + content enhancements ---- */
    var cover = null, covImg = null;
    if (body) {
      var ttl = (postTitle && (postTitle.getAttribute('aria-label') || postTitle.textContent) || d.title).trim();

      /* Images: guarantee alt text, async decode, high priority for the first one (LCP) */
      $$('img', body).forEach(function (im, i) {
        if (!(im.getAttribute('alt') || '').trim()) { im.setAttribute('alt', ttl + ' – image ' + (i + 1)); }
        im.setAttribute('decoding', 'async');
        if (i === 0) { im.setAttribute('fetchpriority', 'high'); im.removeAttribute('loading'); }
      });

      /* Enrich the server-side JSON-LD with word count + reading time */
      var ld = $('#post-ld');
      if (ld) {
        try {
          var clone = body.cloneNode(true);
          $$('.toc, .code-copy, .h-anchor', clone).forEach(function (n) { if (n.parentNode) { n.parentNode.removeChild(n); } });
          var wc = (clone.textContent || '').trim().split(/\s+/).filter(Boolean).length;
          var data = JSON.parse(ld.textContent);
          (data['@graph'] || [data]).forEach(function (n) {
            if (n['@type'] === 'BlogPosting') { n.wordCount = wc; n.timeRequired = 'PT' + Math.max(1, Math.round(wc / 200)) + 'M'; }
          });
          ld.textContent = JSON.stringify(data);
        } catch (e) {}
      }

      /* Cover: first image near the top becomes a parallax cover */
      var kids = Array.prototype.slice.call(body.children);
      var first = $('img', body);
      if (first) {
        var blk = first;
        while (blk && blk.parentNode !== body) { blk = blk.parentNode; }
        if (blk && kids.indexOf(blk) > -1 && kids.indexOf(blk) <= 3 && !(blk.textContent || '').trim()) {
          blk.classList.add('cover-wrap'); cover = blk; covImg = first;
          if (hasIO && !reduce) {
            var cio = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); cio.unobserve(en.target); } }); }, { threshold: 0.1 });
            cio.observe(blk);
          } else { blk.classList.add('in'); }
        }
      }

      /* Drop cap on the opening paragraph */
      var p0 = null;
      for (var k = 0; k < kids.length; k++) { if (kids[k].tagName === 'P') { p0 = kids[k]; break; } }
      if (p0 && (p0.textContent || '').trim().length > 120) { p0.classList.add('dropcap'); }

      /* <mark> highlights paint in as they scroll into view */
      var marks = $$('mark', body);
      if (marks.length && hasIO && !reduce) {
        var mio = new IntersectionObserver(function (es) { es.forEach(function (en) { if (en.isIntersecting) { en.target.classList.add('in'); mio.unobserve(en.target); } }); }, { threshold: 0.6 });
        marks.forEach(function (m) { m.classList.add('mk'); mio.observe(m); });
      }
    }

    /* ---- 3. Copy-link button on the floating share rail ---- */
    $$('[data-copy]').forEach(function (b) {
      b.addEventListener('click', function () {
        var href = location.href.split('#')[0];
        var done = function () { if (window.__toast) { window.__toast('Link copied'); } };
        if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(href).then(done, function () { window.prompt('Copy link:', href); }); }
        else { window.prompt('Copy link:', href); }
      });
    });

    /* ---- 4. One scroll handler: progress ring, share rail, cover parallax ---- */
    var ring = $('#to-top .ring-fg'), C = 144.5;
    var rail = $('.share-rail'), art = $('.post-detail');
    var pending = false;
    function frame() {
      pending = false;
      var y = window.pageYOffset || root.scrollTop, h = root.scrollHeight - window.innerHeight, vh = window.innerHeight;
      if (ring) { ring.style.strokeDashoffset = String(C * (1 - (h > 0 ? Math.min(1, Math.max(0, y / h)) : 0))); }
      if (rail && art) {
        var r = art.getBoundingClientRect();
        rail.classList.toggle('show', r.top < vh * 0.35 && r.bottom > vh * 0.6);
      }
      if (covImg && !reduce) {
        var cr = cover.getBoundingClientRect();
        var p = (cr.top + cr.height / 2 - vh / 2) * -0.05;
        var lim = cr.height * 0.025; covImg.style.setProperty('--py', Math.max(-lim, Math.min(lim, p)) + 'px');
      }
    }
    function req() { if (!pending) { pending = true; window.requestAnimationFrame(frame); } }
    window.addEventListener('scroll', req, { passive: true });
    window.addEventListener('resize', req);
    frame();

    /* ---- 5. Instant navigation: prefetch internal pages on hover (skipped on Save-Data / 2G) ---- */
    var conn = navigator.connection;
    if (!(conn && (conn.saveData || /2g/.test(conn.effectiveType || '')))) {
      var seen = {};
      d.addEventListener('pointerover', function (e) {
        var a = e.target && e.target.closest ? e.target.closest('a[href]') : null;
        if (!a || a.hostname !== location.hostname || a.target === '_blank' || a.hasAttribute('download')) { return; }
        var u = a.href.split('#')[0];
        if (seen[u] || u === location.href.split('#')[0] || /\/search\?|\/feeds\//.test(u)) { return; }
        seen[u] = 1;
        var l = d.createElement('link'); l.rel = 'prefetch'; l.href = u; d.head.appendChild(l);
      }, { passive: true });
    }
  });
})();
